package io.github.nijasc.ktor.svelte.gradle.tasks

import org.junit.jupiter.api.io.TempDir
import java.io.File
import kotlin.test.Test
import kotlin.test.assertContains
import kotlin.test.assertEquals
import kotlin.test.assertFalse

class SecretLeaksTest {
    @TempDir
    lateinit var dir: File

    private val example =
        listOf(
            "# Generated by ktor-svelte from the environment variables the app declares. Do not edit.",
            "",
            "# JDBC URL of the database. Required.",
            "DATABASE_URL=jdbc:postgresql://localhost/app",
            "",
            "# Signs the session cookie. Required. Secret.",
            "SESSION_SIGN_KEY=",
            "",
            "# Token of the mail service. Optional. Secret.",
            "# MAIL_TOKEN=",
            "",
            "# Whether secrets are shown. Either true or false. Default: false.",
            "# SHOW_SECRETS=false",
            "",
        ).joinToString("\n")

    private fun project(): Pair<File, File> {
        val frontend = dir.resolve("frontend").apply { mkdirs() }
        dir.resolve(ENV_EXAMPLE_FILE).writeText(example)
        return dir to frontend
    }

    @Test
    fun `the example file says which variables are secrets`() {
        assertEquals(setOf("SESSION_SIGN_KEY", "MAIL_TOKEN"), declaredSecretNames(example))
        assertEquals(emptySet(), declaredSecretNames(""))
    }

    @Test
    fun `an env file is read line by line, with quotes, exports and comments`() {
        val values =
            envFileValues(
                listOf(
                    "# a comment",
                    "PLAIN=value-one",
                    "export EXPORTED = spaced value   # trailing note",
                    "DOUBLE=\"quoted # not a comment\"",
                    "SINGLE='single quoted'",
                    "EMPTY=",
                    "not an assignment",
                ).joinToString("\r\n"),
            )
        assertEquals(
            mapOf(
                "PLAIN" to "value-one",
                "EXPORTED" to "spaced value",
                "DOUBLE" to "quoted # not a comment",
                "SINGLE" to "single quoted",
                "EMPTY" to "",
            ),
            values,
        )
    }

    @Test
    fun `secrets are the declared ones from the environment and everything private in the env files`() {
        val (project, frontend) = project()
        project
            .resolve(
                ".env",
            ).writeText(
                "STRIPE_KEY=sk_live_1234567890\nPUBLIC_SITE=https://example.com\nSHORT=abc\nNODE_ENV=production\nMAIL_TOKEN=mail-token-from-file\n",
            )
        frontend
            .resolve(
                ".env.production",
            ).writeText("VITE_ANALYTICS=analytics-id-123\nBUILD_FLAG=flag-value-123\nINTERNAL_HOST=internal.example.net\n")
        val environment =
            mapOf(
                "SESSION_SIGN_KEY" to "0123456789abcdef",
                "DATABASE_URL" to "jdbc:postgresql://db/app",
                "PATH" to "/usr/local/bin",
            )
        val secrets = secretValues(project, frontend, setOf("BUILD_FLAG"), environment::get)
        assertEquals(
            listOf(
                "SESSION_SIGN_KEY=0123456789abcdef (declared as a secret)",
                "MAIL_TOKEN=mail-token-from-file (declared as a secret)",
                "STRIPE_KEY=sk_live_1234567890 (.env)",
                "INTERNAL_HOST=internal.example.net (frontend/.env.production)",
            ),
            secrets.map { "${it.name}=${it.value} (${it.origin})" },
        )
    }

    @Test
    fun `a secret found in a built file is reported with its name and the file, never its value`() {
        val (project, frontend) = project()
        val build = frontend.resolve("build").apply { resolve("_app/immutable/chunks").mkdirs() }
        build.resolve("index.html").writeText("<html>fine</html>")
        build.resolve("_app/immutable/chunks/a.js").writeText("const key=\"0123456789abcdef\";export{key}")
        build.resolve("_app/immutable/chunks/b.js").writeBytes(
            byteArrayOf(0, 1, 2) + "xx sk_live_1234567890 yy".toByteArray() + byteArrayOf(-1, -2),
        )
        build.resolve("_app/immutable/chunks/c.js").writeText("const partial=\"0123456789abcde\"")
        val secrets =
            listOf(
                SecretValue("SESSION_SIGN_KEY", "0123456789abcdef", "declared as a secret"),
                SecretValue("STRIPE_KEY", "sk_live_1234567890", ".env"),
                SecretValue("UNUSED_KEY", "never-in-the-build", ".env"),
            )
        val leaks = findLeaks(build, secrets)
        assertEquals(
            listOf("SESSION_SIGN_KEY in _app/immutable/chunks/a.js", "STRIPE_KEY in _app/immutable/chunks/b.js"),
            leaks.map { "${it.name} in ${it.file}" },
        )
        val report = leakReport(leaks)
        assertContains(report, "  SESSION_SIGN_KEY (declared as a secret)  _app/immutable/chunks/a.js")
        assertContains(report, "  STRIPE_KEY (.env)                        _app/immutable/chunks/b.js")
        assertFalse("0123456789abcdef" in report || "sk_live" in report)
        assertEquals(emptyList(), findLeaks(build, emptyList()))
        assertEquals(emptyList(), findLeaks(project.resolve("missing"), secrets))
    }
}
